#!/usr/bin/env python3
"""Author Lab 02 HTML, Markdown and content JSON from verified measurements."""
from pathlib import Path
import json
import html
import re
import shutil

ROOT=Path(__file__).resolve().parents[1]
POST=ROOT/'experiments/lab02/post'
D=json.loads((POST/'data/analysis_results.json').read_text())
R=json.loads((POST/'data/readings.json').read_text())
sections=[]
def section(id,title):
    sections.append(dict(id=id,title=title,blocks=[]))
def block(type,**kw):sections[-1]['blocks'].append(dict(type=type,**kw))
def p(text):block('paragraph',text=text)
def eq(text):block('equation',text=text)
def table(headers,rows,caption):block('table',headers=headers,rows=rows,caption=caption)
def fig(file,caption):block('figure',file=file,caption=caption)
def f(x,n=2):return f'{x:.{n}f}'

