section('compression','بخش سوم: جاروب تک‌تن و P1dB')
p('۱۰ زوج دادهٔ جدول XLSX، منبع اصلی منحنی تک‌تن است. خط مرجع با شیب یک و میانگین اختلاف سطح در سه نقطهٔ کم‌توان اول تعیین شد. از آنجا که خروجی dBFS و ورودی dBm اسمی است، C0 یک ضریب نگاشت سطح است؛ نباید با بهرهٔ توان آنالوگ یا مقدار تنظیم RF gain یکسان گرفته شود.')
eq(f'C0 = mean(Pout − Pin,nom), first 3 points = {f(D["small_signal_offset"],4)}')
