def inline(text):
    return ''.join('<bdi dir="ltr" class="technical">'+html.escape(v)+'</bdi>' if i%2 else html.escape(v) for i,v in enumerate(str(text).split('`')))
def render_figure(file,caption,n):
    return f'<figure><a href="{file}" target="_blank" rel="noopener"><img src="{file}" alt="{html.escape(caption,quote=True)}" loading="lazy"></a><figcaption>شکل {n}. {html.escape(caption)}</figcaption></figure>'

out=[];md=['# '+doc['title'],'','گروه: سروش مومنی (402102538) و مهدی قلمی نوبر (402102284)','مدرس: دکتر سید محمد کرباسی — نیمسال اول ۱۴۰۵–۱۴۰۶',''];nf=nt=0
for s in sections:
    bs=[];md.extend(['## '+s['title'],''])
    for b in s['blocks']:
        t=b['type']
        if t=='paragraph':bs.append('<p>'+inline(b['text'])+'</p>');md.extend([b['text'],''])
        elif t=='equation':bs.append('<div class="formula" dir="ltr">'+html.escape(b['text'])+'</div>');md.extend(['```text',b['text'],'```',''])
        elif t=='table':
            nt+=1
            bs.append('<div class="table-scroll"><table><caption>جدول '+str(nt)+'. '+inline(b['caption'])+'</caption><thead><tr>'+''.join('<th scope="col">'+inline(h)+'</th>' for h in b['headers'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+inline(v)+'</td>' for v in row)+'</tr>' for row in b['rows'])+'</tbody></table></div>')
            md.extend(['| '+' | '.join(b['headers'])+' |','| '+' | '.join(['---']*len(b['headers']))+' |']+['| '+' | '.join(row)+' |' for row in b['rows']]+['',b['caption'],''])
        elif t=='figure':
            nf+=1;bs.append(render_figure(b['file'],b['caption'],nf));md.extend(['!['+b['caption']+']('+b['file']+')',''])
        elif t=='downloads':
            bs.append('<div class="download-grid">'+''.join(f'<a href="{url}">{html.escape(title)}</a>' for url,title in b['items'])+'</div>')
            md.extend(['- ['+title+']('+url+')' for url,title in b['items']]+[''])
        elif t=='references':
            bs.append('<ol class="references">'+''.join(f'<li><a href="{url}">{html.escape(title)}</a></li>' for title,url in b['items'])+'</ol>')
            md.extend([str(i)+'. ['+title+']('+url+')' for i,(title,url) in enumerate(b['items'],1)]+[''])
    out.append(f'<section id="{s["id"]}" class="report-section"><p class="section-index">{sections.index(s)+1:02} / LAB02</p><h2>{s["title"]}</h2>'+''.join(bs)+'</section>')
